"""Build a private aggregate-only cost/stop report; never launches simulations."""
from pathlib import Path
from datetime import datetime, timezone
import hashlib
import json
import sys
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from research.capm_ablation import CASES, STUDY, audit_records, factorial_effects
ROOT = Path('.local') / STUDY
OUT = Path('.local/performance') / STUDY


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    plan = json.loads(Path('research/plans/capm-ablation-v1.json').read_text())
    budget = json.loads((ROOT/'budget.json').read_text())
    results, audits = {}, {}
    for case in CASES:
        path = ROOT / (case+'-summary.json')
        if path.exists():
            results[case] = json.loads(path.read_text())
            try:
                audits[case] = audit_records(results[case], case)
            except ValueError as error:
                audits[case] = dict(passed=False, error=str(error))
    complete = set(results) == set(CASES)
    calendar = len({v['calendar_hash'] for v in audits.values() if v.get('passed')}) == 1
    selected = {v['selection_hash'] for c,v in audits.items() if c.startswith('c') and v.get('passed')}
    selections = len(selected) == 1
    repeats = {}
    for new,old in [('c25_on','capm'),('s25','spy')]:
        if new in results:
            prior = json.loads((Path('.local/capm-spy-v1')/(old+'-summary.json')).read_text())
            repeats[new] = len(prior)==len(results[new]) and all(a['metrics']==b['metrics'] for a,b in zip(prior,results[new]))
    valid = complete and all(v['passed'] for v in audits.values()) and calendar and selections and repeats == {'c25_on':True,'s25':True}
    report = dict(study=STUDY,generated_utc=datetime.now(timezone.utc).isoformat(),eligible=valid,complete=complete,calendar_parity=calendar,selection_parity=selections,prior_control_reproduction=repeats,results=results,audits=audits,plan=plan,budget=budget,effects=factorial_effects(results) if complete else [])
    (OUT/'review.json').write_text(json.dumps(report,indent=2)+'\n')
    (OUT/'index.html').write_text(PAGE.replace('__DATA__',json.dumps(report,separators=(',',':')).replace('<','\\u003c')))
    paths = [Path('research/plans/capm-ablation-v1.json'),Path('research/capm_ablation.py'),Path('scripts/capm_ablation.py'),Path('scripts/build_capm_ablation.py'),Path('scripts/audit_capm_ablation.py'),Path('tests/test_capm_ablation.py')]
    paths += [Path(p) for p in plan['input_hashes']]
    paths += [p for p in ROOT.rglob('*') if p.is_file() and not p.name.endswith('.tmp')]
    paths += [OUT/'review.json',OUT/'index.html']
    paths += [p for p in [OUT/'browser-audit.json', OUT/'review-preview.png'] if p.exists()]
    manifest = dict(study=STUDY,eligible=valid,files=[dict(path=str(p),bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()) for p in sorted(set(paths))])
    (OUT/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
    print(json.dumps(dict(eligible=valid,cases=len(results),annual_rows=sum(len([r for r in rows if r['kind']=='annual']) for rows in results.values()),controls=repeats,calendar=calendar,selections=selections,output=str(OUT))))


PAGE = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CAPM · cost and stop ablation</title><style>
:root{color-scheme:light;--bg:#f3f0e9;--ink:#20332f;--green:#176d63;--line:#d5d9cf}*{box-sizing:border-box}body{background:var(--bg);color:var(--ink);font:15px/1.5 system-ui;margin:0}main{max-width:1400px;margin:32px auto;padding:0 24px}h1{font-size:36px;line-height:1.15;letter-spacing:-1px;margin:10px 0 18px;max-width:850px}h2{font-size:23px;margin:30px 0 12px}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase}.note,footer{color:#617169}.badge{background:#dcebdd;padding:6px 12px;border-radius:20px;display:inline-block}.warn{background:#f2d9c7}.scroll{overflow:auto;border:1px solid var(--line);border-radius:10px;margin:14px 0}table{border-collapse:collapse;background:#fffdf7;width:100%;font-size:13px}th,td{white-space:nowrap;padding:10px;text-align:right;border-bottom:1px solid var(--line)}th:first-child,td:first-child{text-align:left}th{background:#e4e9df}label{display:inline-block;margin:8px 10px 6px 0}select{font:inherit;padding:7px;background:#fffdf7;border:1px solid var(--line);border-radius:6px}.card{background:#fffdf7;padding:18px;border:1px solid var(--line);border-radius:10px}.flow{padding:15px;border-left:3px solid var(--green);background:#e4ebe1}details{background:#fffdf7;padding:16px;border:1px solid var(--line);border-radius:10px;margin:12px 0}summary{cursor:pointer;font-weight:600}a{color:var(--green)}svg{display:block;width:100%;height:320px}.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:13px}.legend span::before{content:'● ';color:var(--c)}footer{font-size:12px;margin:25px 0}@media(max-width:650px){h1{font-size:29px}main{padding:0 16px}}
</style><main><div class="eyebrow">Quant Trading Lab · bounded ablation · 2016–2025</div><h1>How much comes from trading costs, and how much from the stock stop?</h1><div id="status" class="badge"></div><p class="note">$300,000 simulated capital · three explicit-cost settings · CAPM 1% per-stock stop on/off · matching SPY controls. Native quote spreads remain in every setting. No parameter search.</p><div class="flow">Frozen nine cases → reproduced controls → accounting / selection checks → cost × stop effects → annual and temporal review</div><h2>Full-period comparison</h2><label for="cost">Cost setting</label><select id="cost"><option value="all">All three</option><option value="zero">No explicit commissions / added slippage</option><option value="fees">IB commissions only</option><option value="stress">IB commissions + 25bp slippage</option></select><div class="scroll"><table id="full"></table></div><h2>Year by year</h2><label for="metric">Chart metric</label><select id="metric"><option value="ret">Annual return</option><option value="dd">Annual max drawdown</option><option value="sharpe">Annual Sharpe</option><option value="annual_calmar">Annual Calmar</option><option value="uw_fraction">Time underwater</option><option value="longest_uw">Longest underwater, sessions</option><option value="longest_uw_days">Longest underwater, calendar days</option></select><p class="note">At one cost setting, the chart shows CAPM with/without the stock stop and its SPY control. Annual peaks reset; full-period underwater episodes carry across years.</p><div id="legend" class="legend"></div><div id="chart" class="card"></div><div class="scroll"><table id="annual"></table></div><h2>CAPM versus matching SPY</h2><div class="scroll"><table id="benchmark"></table></div><h2>Separating the effects</h2><p class="note">Positive CAGR/return differences mean more growth. Drawdown is signed negative, so a positive DD difference means a shallower decline. For underwater durations, smaller is better. These are closed-loop policy effects: changing costs can alter quantities, entry basis, stops and later trades.</p><label for="effect-period">Contrast period</label><select id="effect-period"><option value="full">Full period</option>__YEAR_OPTIONS__</select><div class="scroll"><table id="effects"></table></div><h2>What we learned</h2><div id="findings" class="card"></div><h2>Execution and exposure</h2><div class="scroll"><table id="execution"></table></div><details open><summary>Qualification and evidence</summary><div id="audit"></div><p><a href="review.json">Aggregate evidence</a> · <a href="manifest.json">Artifact manifest</a> · <a href="https://www.quantconnect.com/project/38512092">Hosted project</a></p></details><details><summary>Definitions and limits</summary><p>Sharpe uses sample daily returns, zero risk-free return and √252. Full Calmar is calendar-day CAGR divided by absolute full closing drawdown. Annual Calmar uses annual total return divided by absolute annual drawdown. Longest underwater calendar duration ends at the last underwater close, excluding recovery day. Open at end describes the latest drawdown; it need not be the longest episode.</p><p>The licensed framework alternative uses 29 fixed legacy stocks, monthly reverse-regression intercept top-two ranking, constant insights, equal weighting and immediate minute execution. Manually subscribed SPY also receives framework insights. The only risk treatment is the source 1% per-security unrealized-profit stop versus the null risk model. It is not a portfolio loss limit. The fixed 25bp slippage level is a stress assumption, not a measured live execution cost. All cases retain a 1% cash-buffer setting and prior-closing-cash 6% debit ACT/360 financing, zero credit, no forced final sale.</p><p>Native lifetime P&amp;L/current-mark and event-fee checks are not independent cash, corporate-action or vendor-data replay. Dense daily NAV, prices and action rows remain hosted. Historical data have already been viewed; there is no untouched OOS evaluation, conventional CAPM-alpha claim, exact hosted tutorial reproduction or live execution validation.</p></details><footer>Development evidence only. Failed attempts remain preserved. No strategy promotion or annual-doubling system follows.</footer></main><script>
const D=__DATA__,meta=D.plan.cases,all=Object.keys(meta),el=id=>document.getElementById(id),pct=v=>v==null?'—':(100*v).toFixed(2)+'%',num=v=>v==null?'—':Number(v).toFixed(2),name=c=>meta[c].strategy==='spy'?'SPY hold':`CAPM · stop ${meta[c].stop_enabled?'on':'off'}`,costLabel={zero:'No explicit costs',fees:'IB fees',stress:'IB fees + 25bp'},full=c=>D.results[c]?.find(r=>r.kind==='full'),annual=c=>D.results[c]?.filter(r=>r.kind==='annual').sort((a,b)=>a.year-b.year)||[],colors=['#176d63','#b0643b','#5472aa','#9c7530','#79728f','#c54148','#738849','#386f82','#5c584f'];
el('status').textContent=D.eligible?'Completed · all nine cases qualified':'Partial / qualification incomplete';if(!D.eligible)el('status').classList.add('warn');
function table(id,headers,rows){el(id).innerHTML='<thead><tr>'+headers.map(h=>`<th>${h}</th>`).join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(v=>`<td>${v}</td>`).join('')+'</tr>').join('')+'</tbody>'}
function chosen(){return all.filter(c=>full(c)&&(el('cost').value==='all'||meta[c].cost_mode===el('cost').value))}
function render(){const cs=chosen();table('full',['Case / costs','CAGR','Total return','Max DD','Sharpe','Calmar','Underwater','Longest sessions','Calendar days','Open at end'],cs.map(c=>{let m=full(c).metrics;return [`${name(c)} · ${costLabel[meta[c].cost_mode]}`,pct(m.cagr),pct(m.ret),pct(m.dd),num(m.sharpe),num(m.calmar),pct(m.uw_fraction),m.longest_uw,m.longest_uw_days,m.censored?'Yes':'No']}));table('annual',['Year / case / costs','Return','Max DD','Sharpe','Calmar','Underwater','Longest sessions','Calendar days','Open at end'],Array.from({length:10},(_,i)=>2016+i).flatMap(y=>cs.map(c=>{let r=annual(c).find(r=>r.year===y);if(!r)return [];let m=r.metrics;return [`${y} · ${name(c)} · ${costLabel[meta[c].cost_mode]}`,pct(m.ret),pct(m.dd),num(m.sharpe),num(m.annual_calmar),pct(m.uw_fraction),m.longest_uw,m.longest_uw_days,m.censored?'Yes':'No']})));table('execution',['Case / costs','Fills','Notional USD','Fees USD','Financing USD','Mean gross','Max gross','Cash-only closes','Selections','Book residual'],cs.map(c=>{let a=full(c).audit;return [`${name(c)} · ${costLabel[meta[c].cost_mode]}`,a.fills,num(a.fill_notional_usd),num(a.fees),num(a.interest),num(a.mean_gross)+'x',num(a.max_gross)+'x',a.cash_only_days,a.selection_count,num(a.native_book_residual)]}));chart(cs)}
function chart(cs){let key=el('metric').value,vals=cs.flatMap(c=>annual(c).map(r=>r.metrics[key]).filter(v=>v!=null));if(!vals.length){el('chart').textContent='No qualified results yet';return}let lo=Math.min(0,...vals),hi=Math.max(0,...vals),pad=Math.max((hi-lo)*.08,.01);lo-=pad;hi+=pad;let y=v=>270-(v-lo)/(hi-lo)*235,body=`<line x1="55" x2="1150" y1="${y(0)}" y2="${y(0)}" stroke="#a2aca3"/>`;for(let j=0;j<5;j++){let v=lo+(hi-lo)*j/4;body+=`<text x="48" y="${y(v)+4}" text-anchor="end" font-size="11">${['ret','dd','uw_fraction'].includes(key)?pct(v):num(v)}</text>`}cs.forEach((c,j)=>{let rows=annual(c),color=colors[all.indexOf(c)];body+=`<polyline points="${rows.map((r,i)=>`${75+i*117},${y(r.metrics[key]??0)}`).join(' ')}" fill="none" stroke="${color}" stroke-width="2"/>`;rows.forEach((r,i)=>{let v=r.metrics[key];if(v!=null)body+=`<circle cx="${75+i*117}" cy="${y(v)}" r="4" fill="${color}"><title>${r.year} ${name(c)} ${costLabel[meta[c].cost_mode]}: ${v}</title></circle>`})});for(let i=0;i<10;i++)body+=`<text x="${75+i*117}" y="305" text-anchor="middle" font-size="12">${2016+i}</text>`;el('chart').innerHTML=`<svg viewBox="0 0 1160 320" role="img" aria-label="Annual metric comparison">${body}</svg>`;el('legend').innerHTML=cs.map(c=>`<span style="--c:${colors[all.indexOf(c)]}">${name(c)} · ${costLabel[meta[c].cost_mode]}</span>`).join('')}
function benchmark(){const spys={zero:'s0',fees:'sf',stress:'s25'};table('benchmark',['CAPM / costs','CAGR Δ pp vs SPY','DD Δ pp','Calmar Δ','Annual return wins / 10','Longest UW sessions Δ'],all.filter(c=>meta[c].strategy==='capm'&&full(c)&&full(spys[meta[c].cost_mode])).map(c=>{let b=spys[meta[c].cost_mode],a=full(c).metrics,m=full(b).metrics,wins=annual(c).filter(r=>r.metrics.ret>annual(b).find(s=>s.year===r.year).metrics.ret).length;return [name(c)+' · '+costLabel[meta[c].cost_mode],num(100*(a.cagr-m.cagr)),num(100*(a.dd-m.dd)),num(a.calmar-m.calmar),wins+' / 10',a.longest_uw-m.longest_uw]}))}benchmark();
if(D.eligible){let a=full('cf_on').metrics,b=full('cf_off').metrics;el('findings').innerHTML=`<p>With commissions only, the stock stop changes CAGR ${pct(b.cagr)} → ${pct(a.cagr)}, drawdown ${pct(b.dd)} → ${pct(a.dd)}, and longest underwater ${b.longest_uw} → ${a.longest_uw} sessions. A shallower full drawdown does not imply better growth or recovery.</p><p>At 25bp stress, the stop-on versus stop-off CAGR difference is ${num(100*(full('c25_on').metrics.cagr-full('c25_off').metrics.cagr))} percentage points. Compared with the same stop difference under no explicit costs, the cost × stop interaction is ${num(100*((full('c25_on').metrics.cagr-full('c25_off').metrics.cagr)-(full('c0_on').metrics.cagr-full('c0_off').metrics.cagr)))} points. These are policy contrasts, not additive dollar loss attribution.</p><p>${all.filter(c=>meta[c].strategy==='capm').every(c=>full(c).metrics.cagr<full({zero:'s0',fees:'sf',stress:'s25'}[meta[c].cost_mode]).metrics.cagr)?'All six CAPM variants have lower CAGR than matching SPY.':'Some CAPM cases exceed matching SPY; joint risk and audit evidence still matters.'} No CAPM variant meets a 30% continuous closing-drawdown tolerance. Keep this alternative as a negative development baseline; no promotion or further threshold search follows this bounded test.</p>`}else el('findings').textContent='Final interpretation waits for all nine cases and qualification.';
const effectName=e=>e.effect==='stop_on_minus_off'?`Stop on − off · ${costLabel[e.cost]}`:e.effect==='total_cost_stop_interaction'?'Cost × stop interaction':`${e.effect==='fees_minus_zero'?'Fees − no explicit costs':'25bp stress − fees'} · stop ${e.stop?'on':'off'}`;
function effects(){let p=el('effect-period').value,rows=D.effects.filter(e=>p==='full'?e.kind==='full':e.year===Number(p)),groups=[...new Set(rows.map(effectName))],keys=p==='full'?['cagr','dd','sharpe','calmar','uw_fraction','longest_uw','longest_uw_days']:['ret','dd','sharpe','annual_calmar','uw_fraction','longest_uw','longest_uw_days'];table('effects',['Contrast',p==='full'?'CAGR Δ pp':'Return Δ pp','DD Δ pp','Sharpe Δ','Calmar Δ','UW Δ pp','Sessions Δ','Days Δ'],groups.map(g=>[g,...keys.map(k=>{let v=rows.find(e=>effectName(e)===g&&e.metric===k)?.value;return v==null?'—':['cagr','ret','dd','uw_fraction'].includes(k)?num(100*v):num(v)})]))}
el('effect-period').innerHTML=el('effect-period').innerHTML.replace('__YEAR_OPTIONS__','');for(let y=2016;y<=2025;y++)el('effect-period').insertAdjacentHTML('beforeend',`<option value="${y}">${y}</option>`);el('cost').addEventListener('change',render);el('metric').addEventListener('change',()=>chart(chosen()));el('effect-period').addEventListener('change',effects);render();effects();el('audit').innerHTML=`<p>${Object.keys(D.results).length}/9 cases exported. Calendar parity: ${D.calendar_parity}. CAPM monthly selection parity: ${D.selection_parity}. Prior 25bp controls: ${JSON.stringify(D.prior_control_reproduction)}. Budget: ${D.budget.attempts.length}/11 attempts; ${D.budget.status}.</p><p>${Object.entries(D.audits).map(([c,a])=>c+': '+(a.passed?'passed':a.error)).join('<br>')}</p>`;
</script></html>'''.replace('__YEAR_OPTIONS__','')

if __name__ == '__main__':
    main()
